package earth.worldwind.draw

import earth.worldwind.geom.Matrix4
import earth.worldwind.layer.shadow.ShadowCaster
import earth.worldwind.layer.shadow.applyShadowReceiverUniforms
import earth.worldwind.render.program.TriangleShaderProgram
import earth.worldwind.util.Pool
import earth.worldwind.util.kgl.GL_CULL_FACE
import earth.worldwind.util.kgl.GL_DEPTH_TEST
import earth.worldwind.util.kgl.GL_FLOAT
import earth.worldwind.util.kgl.GL_TEXTURE0
import kotlin.jvm.JvmStatic

open class DrawableShape protected constructor(): Drawable, SightlineOccluder, ShadowCaster {
    val drawState = DrawShapeState()
    private var pool: Pool<DrawableShape>? = null
    private val mvpMatrix = Matrix4()
    private val modelMatrix = Matrix4()

    override val shadowCasterCenter get() = if (drawState.boundingRadius > 0.0) drawState.boundingCenter else null
    override val shadowCasterRadius get() = drawState.boundingRadius

    companion object {
        val KEY = DrawableShape::class

        @JvmStatic
        fun obtain(pool: Pool<DrawableShape>): DrawableShape {
            val instance = pool.acquire() ?: DrawableShape()
            instance.pool = pool
            return instance
        }
    }

    override fun recycle() {
        drawState.reset()
        pool?.release(this)
        pool = null
    }

    override fun draw(dc: DrawContext) {
        if (drawState.isOccluderOnly) return // queued only for the sightline depth pass
        // TODO shape batching
        val program = drawState.program as? TriangleShaderProgram ?: return // program unspecified
        if (!program.useProgram(dc)) return // program failed to build
        if (drawState.vertexBuffer?.bindBuffer(dc) != true) return  // vertex buffer unspecified or failed to bind
        if (drawState.elementBuffer?.bindBuffer(dc) != true) return  // element buffer unspecified or failed to bind

        // Use the draw context's pick mode.
        program.enablePickMode(dc.isPickMode)

        // Use the draw context's modelview projection matrix, transformed to shape local coordinates.
        if (drawState.depthOffset != 0.0) {
            mvpMatrix.copy(dc.projection).offsetProjectionDepth(drawState.depthOffset)
            program.loadClipDistance((mvpMatrix.m[11] / (mvpMatrix.m[10] - 1.0)).toFloat() / 2.0f) // nearPlane / 2.0f
            mvpMatrix.multiplyByMatrix(dc.modelview)
        } else {
            program.loadClipDistance((dc.projection.m[11] / (dc.projection.m[10] - 1.0)).toFloat() / 2.0f)  // nearPlane / 2.0f
            mvpMatrix.copy(dc.modelviewProjection)
        }
        mvpMatrix.multiplyByTranslation(drawState.vertexOrigin.x, drawState.vertexOrigin.y, drawState.vertexOrigin.z)
        program.loadModelviewProjection(mvpMatrix)

        // Camera-relative model transform (translation only). The fragment shader adds this
        // matrix's 4th column to localPos for shadow sampling; keeping it eye-relative keeps
        // the float32 math precise (see ShadowReceiverGlsl). Uploaded unconditionally so the
        // varying-derived position is always valid.
        modelMatrix.setToTranslation(
            drawState.vertexOrigin.x - dc.eyePoint.x,
            drawState.vertexOrigin.y - dc.eyePoint.y,
            drawState.vertexOrigin.z - dc.eyePoint.z,
        )
        program.loadModelMatrix(modelMatrix)

        // Lighting: enable only for filled triangles (lines have no meaningful face normal),
        // outside pick mode (shader gates it too, but skipping the uniform upload saves work).
        val lightingActive = drawState.enableLighting && !drawState.isLine && !dc.isPickMode
        program.enableLighting(lightingActive)
        if (lightingActive) {
            program.loadLightDirection(dc.lightDirection)
            program.loadUpDirection(dc.upDirection)
        }

        // Bind cascade shadow textures and load receiver uniforms once per draw. Picks bypass,
        // and per-shape opt-out (`shadowMode = DISABLED` or `CAST_ONLY`) skips receive too.
        dc.applyShadowReceiverUniforms(program, drawState.shadowMode.receivesShadows)

        // Disable triangle back face culling if requested.
        if (!drawState.enableCullFace) dc.gl.disable(GL_CULL_FACE)

        // Disable depth testing if requested.
        if (!drawState.enableDepthTest) dc.gl.disable(GL_DEPTH_TEST)

        // Disable depth writing if requested.
        if (!drawState.enableDepthWrite) dc.gl.depthMask(false)

        try {
            // Make multi-texture unit 0 active.
            dc.activeTextureUnit(GL_TEXTURE0)

            // Use the shape's vertex point attribute and vertex texture coordinate attribute.
            dc.gl.enableVertexAttribArray(1 /*vertexTexCoord*/)
            dc.gl.enableVertexAttribArray(2 /*vertexTexCoord*/)
            dc.gl.enableVertexAttribArray(3 /*vertexTexCoord*/)

            if (drawState.isLine) {
                program.enableOneVertexMode(false)
                program.loadScreen(dc.viewport.width.toFloat(), dc.viewport.height.toFloat())
                dc.gl.vertexAttribPointer(0 /*pointA*/, 4, GL_FLOAT, false, 20, 0)
                dc.gl.vertexAttribPointer(1 /*pointB*/, 4, GL_FLOAT, false, 20, 80)
                dc.gl.vertexAttribPointer(2 /*pointC*/, 4, GL_FLOAT, false, 20, 160)
                dc.gl.vertexAttribPointer(3 /*texCoord*/, 1, GL_FLOAT, false, 20, 96)
            } else {
                program.enableOneVertexMode(true)
                dc.gl.vertexAttribPointer(0 /*vertexPoint*/, 3, GL_FLOAT, false, drawState.vertexStride, 0)
                dc.gl.vertexAttribPointer(1 /*vertexPoint*/, 3, GL_FLOAT, false, drawState.vertexStride, 0)
                dc.gl.vertexAttribPointer(2 /*vertexPoint*/, 3, GL_FLOAT, false, drawState.vertexStride, 0)
            }
            // Draw the specified primitives.
            for (idx in 0 until drawState.primCount) {
                val prim = drawState.prims[idx]
                program.loadColor(prim.color)
                program.loadOpacity(prim.opacity)
                if (prim.texture?.bindTexture(dc) == true) {
                    program.loadTexCoordMatrix(prim.texCoordMatrix)
                    program.enableTexture(true)
                } else {
                    program.enableTexture(false)
                    // prevent "RENDER WARNING: there is no texture bound to unit 0"
                    dc.defaultTexture.bindTexture(dc)
                }
                if (drawState.isLine) {
                    program.loadLineWidth(prim.lineWidth)
                } else {
                    dc.gl.vertexAttribPointer(
                        3 /*vertexTexCoord*/, prim.texCoordAttrib.size, GL_FLOAT, false,
                        drawState.vertexStride, prim.texCoordAttrib.offset
                    )
                    dc.gl.lineWidth(prim.lineWidth)
                }
                dc.gl.drawElements(prim.mode, prim.count, prim.type, prim.offset)
            }
        } finally {
            // Restore the default WorldWind OpenGL state.
            if (!drawState.enableCullFace) dc.gl.enable(GL_CULL_FACE)
            if (!drawState.enableDepthTest) dc.gl.enable(GL_DEPTH_TEST)
            if (!drawState.enableDepthWrite) dc.gl.depthMask(true)
            dc.gl.lineWidth(1f)
            dc.gl.disableVertexAttribArray(1 /*vertexTexCoord*/)
            dc.gl.disableVertexAttribArray(2 /*vertexTexCoord*/)
            dc.gl.disableVertexAttribArray(3 /*vertexTexCoord*/)
        }
    }

    override fun drawSightlineDepth(dc: DrawContext, sightline: DrawableSightline) {
        // Line shapes are wide expanded triangles with a non-position vertex layout - they
        // can't be reused as opaque occluders, and they're not occluding volumes anyway.
        if (!drawState.isLine) sightline.drawShapeStateOccluder(dc, drawState, drawState.vertexStride)
    }

    override fun drawShadowDepth(dc: DrawContext, shadow: DrawableShadow) {
        // Per-shape opt-out: `shadowMode = DISABLED` or `RECEIVE_ONLY` skips the depth pass.
        // Same rationale as [drawSightlineDepth]: lines are screen-space-expanded triangles
        // and would alias as silhouettes in the shadow map.
        if (!drawState.shadowMode.castsShadows || drawState.isLine) return
        shadow.drawShapeStateOccluder(dc, drawState, drawState.vertexStride)
    }
}