package earth.worldwind.draw

import earth.worldwind.geom.Matrix4
import earth.worldwind.layer.starfield.StarFieldProgram
import earth.worldwind.render.Texture
import earth.worldwind.render.buffer.BufferObject
import earth.worldwind.util.Logger
import earth.worldwind.util.Pool
import earth.worldwind.util.kgl.*
import kotlin.jvm.JvmStatic

open class DrawableStarField protected constructor(): Drawable {
    val matrix = Matrix4()
    var julianDate = 0.0
    var minMagnitude = 0.0f
    var maxMagnitude = 0.0f
    var numStars = 0
    var isShowSun = false
    var sunSize = 0.0f
    var sunTexture: Texture? = null
    var starsPositionsBuffer: BufferObject? = null
    var sunPositionsBuffer: BufferObject? = null
    var program: StarFieldProgram? = null
    private var pool: Pool<DrawableStarField>? = null

    companion object {
        var maxGlPointSize = 0f
        // GL clamps oversized point sizes silently; log the warning once so it doesn't
        // flood the console at frame rate (default sunSize is 128, macOS Core caps at 64).
        private var warnedSunSizeExceeds = false

        val KEY = DrawableStarField::class

        @JvmStatic
        fun obtain(pool: Pool<DrawableStarField>): DrawableStarField {
            val instance = pool.acquire() ?: DrawableStarField()
            instance.pool = pool
            return instance
        }
    }

    private fun getValidPointSizeRangeMax(dc: DrawContext, pname: Int): Float? {
        val range = dc.gl.getParameterfv(pname)
        val min = range[0]
        val max = range[1]
        return if (max >= min && max > 0f && max.isFinite()) max else null
    }

    private fun resolveMaxGlPointSize(dc: DrawContext): Float {
        return getValidPointSizeRangeMax(dc, GL_ALIASED_POINT_SIZE_RANGE)
            ?: getValidPointSizeRangeMax(dc, GL_SMOOTH_POINT_SIZE_RANGE)
            ?: 1f
    }

    override fun recycle() {
        starsPositionsBuffer = null
        sunPositionsBuffer = null
        sunTexture = null
        program = null
        pool?.release(this)
        pool = null
    }

    override fun draw(dc: DrawContext) {
        val program = program ?: return // program unspecified
        if (!program.useProgram(dc)) return // program failed to build
        try {
            dc.gl.depthMask(false)
            drawStars(dc, program, starsPositionsBuffer)
            if (isShowSun) drawSun(dc, program, sunPositionsBuffer, sunTexture)
        } finally {
            dc.gl.depthMask(true)
        }
    }

    protected open fun drawStars(dc: DrawContext, program: StarFieldProgram, buffer: BufferObject?) {
        if (buffer?.bindBuffer(dc) != true) return
        dc.gl.vertexAttribPointer(0, 4, GL_FLOAT, false, 0, 0)
        // This subtraction does not work properly on the GPU due to precision loss. It must be done on the CPU.
        program.loadModelviewProjection(matrix)
        program.loadNumDays((julianDate - 2451545.0).toFloat())
        program.loadMagnitudeRange(minMagnitude, maxMagnitude)
        program.loadTextureEnabled(false)
        dc.gl.drawArrays(GL_POINTS, 0, numStars)
    }

    protected open fun drawSun(
        dc: DrawContext, program: StarFieldProgram, sunBuffer: BufferObject?, sunTexture: Texture?
    ) {
        if (maxGlPointSize == 0f) maxGlPointSize = resolveMaxGlPointSize(dc)

        if (sunSize > maxGlPointSize && !warnedSunSizeExceeds) {
            warnedSunSizeExceeds = true
            Logger.log(Logger.WARN, "StarFieldLayer - sunSize $sunSize exceeds GL max point size $maxGlPointSize; clamped by driver")
        }

        if (sunBuffer?.bindBuffer(dc) != true) return
        if (sunTexture?.bindTexture(dc) != true) return
        dc.gl.vertexAttribPointer(0, 4, GL_FLOAT, false, 0, 0)
        program.loadTextureEnabled(true)
        dc.gl.drawArrays(GL_POINTS, 0, 1)
    }
}