open class RenderContext {
    companion object {
        private const val MAX_PICKED_OBJECT_ID = 0xFFFFFF
        /**
         * Maximum number of shape / label / placemark assemblies allowed per frame. Mostly a
         * fail-safe — the per-frame [maxAssemblyTimeMillis] cap is the real throttle for heavy
         * shapes; this count just guards against pathological cases (e.g. a user setting the time
         * cap to [Long.MAX_VALUE]). Set to [Int.MAX_VALUE] to disable.
         */
        var maxAssembliesPerFrame = 500
        /**
         * Soft cap (in milliseconds) on accumulated shape geometry assembly time per frame,
         * charged via [recordAssemblyTime] around each assembly. Once the accumulated time
         * crosses this threshold further [canAssembleGeometry] calls return false and defer to
         * the next frame, so a batch of heavy shapes (e.g. complex polygons with thousands of
         * vertices) can't stall the Choreographer callback. Only actual assembly time counts —
         * unrelated render work between assemblies (e.g. 3D-Tiles traversal) does not burn the
         * budget. Adapts to per-shape complexity in a way the [maxAssembliesPerFrame] count
         * cannot. Cooperative — an assembly that starts under budget runs to completion and may
         * itself exceed the cap. Set to [Long.MAX_VALUE] to disable.
         */
        var maxAssemblyTimeMillis = 8L
        /**
         * Page-aligned size used to charge a [BufferObject] against [RenderResourceCache]. GPU
         * drivers (Adreno KGSL, recent Mali, desktop Mesa) back every buffer with at least one
         * mmap'd page even when the data is a few hundred bytes, so the kernel's GPU shared-memory
         * pool runs out by *buffer count* long before raw byte volume becomes a concern. Charging
         * the cache by `ceil(bytes / pageSize) * pageSize` makes its LRU eviction react to the
         * real GPU footprint rather than the data-bytes lower bound. 4 KB matches the common ARM
         * and x86_64 page size; some recent Pixel/Galaxy phones run a 16 KB page-size kernel but
         * the buffer is still aligned at 4 KB inside that — undercount remains safe, the bound
         * just isn't perfectly tight there.
         */
        @PublishedApi internal const val BUFFER_GPU_FOOTPRINT_PAGE_SIZE = 4096

        // @PublishedApi (instead of `private`) so the [offerGLBufferUpload] inline call site can
        // resolve this from external compilation units. Logically internal to RenderContext.
        @PublishedApi internal fun bufferGpuFootprint(bytes: Int): Int =
            if (bytes <= 0) 0
            else ((bytes + BUFFER_GPU_FOOTPRINT_PAGE_SIZE - 1) / BUFFER_GPU_FOOTPRINT_PAGE_SIZE) * BUFFER_GPU_FOOTPRINT_PAGE_SIZE
    }

