    var fogDensity = 0.0
    /** Frame snapshot of [earth.worldwind.FogSse.screenSpaceErrorFactor]. */
    var fogScreenSpaceErrorFactor = 0.0
    /** Distance beyond which a tile is fully fogged and may be culled from assembly. */
    var fullFogDistance = Double.MAX_VALUE
    var atmosphereAltitude = 0.0
    var viewingDistance = 0.0
    var pixelSize = 0.0
    var lookAtPosition: Position? = null
    var globeState: Globe.State? = null
    var elevationModelTimestamp = 0L
    /** Wall-time nanos of the previous GL-thread frame (set by [earth.worldwind.WorldWind.drawFrame]).
     *  Generic GL-pressure signal for producers that emit GL-bound work and want to throttle when
     *  the GL thread ran long. */
    @Volatile var lastGLFrameWorkNanos: Long = 0L
    /**
     * Mirrors [earth.worldwind.draw.DrawContext.contextVersion] for this frame. Renderables
     * that own GPU handles outside [RenderResourceCache] can compare this against a cached
     * value during `doRender` to detect a GL context teardown (e.g. Android pause / resume)
     * and reset their stale references.
     */
    var contextVersion: Long = 0L
    /** Mirrors [earth.worldwind.util.kgl.Kgl.supportsSharedElementArrayBuffer] for this frame's
     *  GL context — render-thread upload paths (no GL `Kgl` in reach) read it to decide whether
     *  index data shares the vertex buffer or needs its own EBO. See `uploadMeshContent`. */
    var supportsSharedElementArrayBuffer: Boolean = true
    var cameraPoint = Vec3()
    /**
     * World-space (Cartesian) unit vector pointing **toward** the light source. Resolved by
     * [earth.worldwind.WorldWind] each frame before any layer renders: the sun position when
     * `WorldWind.time` is set, a custom `WorldWind.lightDirectionProvider` direction, or the
     * surface normal at the camera's geographic position (a "light from above the user's foot
     * point") as the default. Shape lighting, shadows and atmospheric scattering all read the
     * same vector.
     */
    val lightDirection = Vec3(0.0, 0.0, 1.0)
    /**
     * Scene time mirrored from [earth.worldwind.WorldWind.time] each frame, or null when no
     * scene time is set. Drives every time-dependent feature: the sun-from-time
     * [lightDirection], the atmosphere day/night terminator and night texture, and star/sun
     * positions in the star field.
     */
    var time: Instant? = null
    /**
     * Per-frame state for the directional sun-shadow pipeline. Non-null when a
     * [earth.worldwind.layer.shadow.ShadowLayer] is in the layer list and has computed
     * cascades for this frame; null otherwise. Snapshotted into [earth.worldwind.frame.Frame]
     * at the end of render and propagated to [earth.worldwind.draw.DrawContext.shadowState]
     * for the draw phase.
