    var shadowState: ShadowState? = null
    /**
     * View-depth extent of shadow-relevant content accumulated while the **previous** regular
     * frame's drawables were offered. Consumed by [earth.worldwind.layer.shadow.ShadowLayer]
     * to fit cascade splits — the shadow layer renders before content layers, so the current
     * frame's own accumulation ([shadowSceneBoundsCurrent]) is still empty at that point.
     * One frame of latency is invisible in practice.
     */
    val shadowSceneBounds = ShadowSceneBounds()
    /** Accumulation target for the frame being rendered — rolled into [shadowSceneBounds] on [reset]. */
    val shadowSceneBoundsCurrent = ShadowSceneBounds()
    /**
     * `true` when an enabled [earth.worldwind.layer.shadow.ShadowLayer] is present in [layers]
     * for this frame. Computed once at the start of [earth.worldwind.WorldWind.renderFrame]
     * before any [Layer.render] runs, so receivers that touch every visible fragment
     * (surface tiles, atmosphere ground) can pick the smaller-binary no-shadow shader
     * variant up-front. Independent of [shadowState], which is populated later by
     * [earth.worldwind.layer.shadow.ShadowLayer.doRender].
     */
    var hasShadowLayer: Boolean = false
    /**
     * `true` when the frame's [earth.worldwind.layer.shadow.ShadowLayer] has
     * `terrainLambert > 0`. Gates per-tile terrain normal buffers in the tessellator, so
     * shadow-only scenes (relief off) never pay the normals pipeline. Snapshotted alongside
     * [hasShadowLayer].
     */
    var isTerrainReliefEnabled: Boolean = false
    /**
     * Per-frame flag set by [earth.worldwind.shape.RealtimeSightline.makeDrawable]
     * when a visible sightline is enqueued. Read by `Ogc3dTilesProgram.get` (and any other
     * program that splices [earth.worldwind.layer.sightline.SightlineReceiverGlsl]) to pick
     * the sightline-aware variant up front. Independent of [DrawContext.sightlineState],
