    var hasActiveSightline: Boolean = false
    /** Set by [earth.worldwind.layer.ogc3d.Ogc3dTilesLayer.doRender] when a mesh layer is
     *  active this frame. Propagated to [DrawContext.hasGroundCoverageMask] via [earth.worldwind.frame.Frame]. */
    var hasGroundCoverageMask: Boolean = false
    /** Per-frame coverage sectors published by 3D-Tile mesh layers — terrain tiles outside
     *  every region skip the GROUND_COVERED_BIT stencil test so distant mountains still
     *  occlude mesh content via depth test. */
    val groundCoverageRegions = mutableListOf<Sector>()
    /** Per-frame 3D-Tile mesh drawables registered for surface-shape draping. Propagated to
     *  [DrawContext.groundOverlaySurfaces] via [earth.worldwind.frame.Frame]. */
    val groundOverlaySurfaces = mutableListOf<earth.worldwind.draw.GroundOverlaySurface>()
    val viewport = Viewport()
    val projection = Matrix4()
    val modelview = Matrix4()
    val modelviewProjection = Matrix4()
    val frustum = Frustum()
    /**
     * Bounds of sightlines registered this frame. Populated by [Omni|Directional]Sightline.doRender,
     * consulted by AbstractShape to keep off-camera shapes alive as occluders. Order matters: a
     * shape's doRender only sees sightlines whose doRender has already run, so place sightlines
     * earlier in layer order than the shapes they should shadow.
     */
    val sightlineBounds = mutableListOf<BoundingSphere>()
    var uploadQueue : UploadQueue? = null
    var drawableQueue: DrawableQueue? = null
    var drawableTerrain: DrawableQueue? = null
    var pickedObjects: PickedObjectList? = null
    var pickDeferred: CompletableDeferred<PickedObjectList>? = null
    var pickViewport: Viewport? = null
    var pickPoint: Vec2? = null
    var pickRay: Line? = null
    var isPickMode = false
    var isRedrawRequested = false
        protected set
    private var pickedObjectId = 0
    private var pixelSizeFactor = 0.0
    private var assembliesThisFrame = 0
    private var assemblyNanosThisFrame = 0L
    private val userProperties = mutableMapOf<Any, Any>()
    val drawablePools = HashMap<KClass<*>, Pool<*>>()
    private var textRenderer = TextRenderer(this)
    private val scratchTextCacheKey = TextCacheKey()
    private val scratchVector = Vec3()

    val tessellator: GLUtessellator by lazy { GLU.gluNewTess() }

    /** Drops all shader programs, releasing each one's GL handles. Called after a GL context loss. */
    fun releaseShaderPrograms(dc: DrawContext) {
        for (program in shaderPrograms.values) program.release(dc)
        shaderPrograms.clear()
    }

    open fun reset() {
        densityFactor = 1f
        horizonDistance = 0.0
        fogDensity = 0.0
        fogScreenSpaceErrorFactor = 0.0
        fullFogDistance = Double.MAX_VALUE
        atmosphereAltitude = 0.0
        viewingDistance = 0.0
        pixelSize = 0.0
        lookAtPosition = null
        globeState = null
        elevationModelTimestamp = 0L
        cameraPoint.set(0.0, 0.0, 0.0)
        lightDirection.set(0.0, 0.0, 1.0)
        time = null
        shadowState = null
        // Roll the completed frame's bounds into the consumable slot; pick frames render a
        // reduced scene and are discarded.
        if (!isPickMode && shadowSceneBoundsCurrent.hasData) shadowSceneBounds.copyFrom(shadowSceneBoundsCurrent)
        shadowSceneBoundsCurrent.clear()
        hasShadowLayer = false
        isTerrainReliefEnabled = false
        hasActiveSightline = false
        hasGroundCoverageMask = false
        groundCoverageRegions.clear()
        groundOverlaySurfaces.clear()
        viewport.setEmpty()
        projection.setToIdentity()
        modelview.setToIdentity()
        modelviewProjection.setToIdentity()
        frustum.setToUnitFrustum()
        sightlineBounds.clear()
        uploadQueue = null
        drawableQueue = null
        drawableTerrain = null
        pickedObjects = null
        pickDeferred = null
        pickViewport = null
        pickPoint = null
        pickRay = null
        isPickMode = false
        pickedObjectId = 0
        isRedrawRequested = false
        pixelSizeFactor = 0.0
        assembliesThisFrame = 0
        assemblyNanosThisFrame = 0L
        userProperties.clear()
    }

    fun requestRedraw() { isRedrawRequested = true }

    fun canAssembleGeometry(): Boolean {
        if (assembliesThisFrame >= maxAssembliesPerFrame
            || assemblyNanosThisFrame >= maxAssemblyTimeMillis * 1_000_000L) {
            isRedrawRequested = true
            return false
        }
        assembliesThisFrame++
        return true
    }

    /** Charges [nanos] of actual geometry assembly time against this frame's [maxAssemblyTimeMillis] budget. */
    fun recordAssemblyTime(nanos: Long) { assemblyNanosThisFrame += nanos }

    /**
     * Returns the height of a pixel at a given distance from the eye point. This method assumes the model of a screen
     * composed of rectangular pixels, where pixel coordinates denote infinitely thin space between pixels. The units of
     * the returned size are in meters per pixel.
     * <br>
     * The result of this method is undefined if the distance is negative.
     *
     * @param distance the distance from the eye point in meters
     *
     * @return the pixel height in meters per pixel
     */
    fun pixelSizeAtDistance(distance: Double): Double {
        if (pixelSizeFactor == 0.0) { // cache the scaling factor used to convert distances to pixel sizes
            val fov = camera.fieldOfView
            val tanFov2 = tan(fov.inRadians * 0.5)
            pixelSizeFactor = 2 * tanFov2 / viewport.height
        }
        return distance * pixelSizeFactor
    }

    /**
     * Projects a Cartesian point to screen coordinates. The resultant screen point is in OpenGL screen coordinates,
     * with the origin in the bottom-left corner and axes that extend up and to the right from the origin.
     * <br>
     * This stores the projected point in the result argument, and returns a boolean value indicating whether or not the
     * projection is successful. This returns false if the Cartesian point is clipped by the near clipping plane or the
     * far clipping plane.
     *
     * @param modelPoint the Cartesian point to project
     * @param result     a pre-allocated [Vec3] in which to return the projected point
     *
     * @return true if the transformation is successful, otherwise false
     */
    fun project(modelPoint: Vec3, result: Vec3): Boolean {
        // TODO consider consolidating this with Matrix4.project and moving projectWithDepth to Matrix4
        // Transform the model point from model coordinates to eye coordinates then to clip coordinates. This
        // inverts the Z axis and stores the negative of the eye coordinate Z value in the W coordinate.
        val mx = modelPoint.x
        val my = modelPoint.y
        val mz = modelPoint.z
        val m = modelviewProjection.m
        var x = m[0] * mx + m[1] * my + m[2] * mz + m[3]
        var y = m[4] * mx + m[5] * my + m[6] * mz + m[7]
        var z = m[8] * mx + m[9] * my + m[10] * mz + m[11]
        val w = m[12] * mx + m[13] * my + m[14] * mz + m[15]
        if (w == 0.0) return false

        // Complete the conversion from model coordinates to clip coordinates by dividing by W. The resultant X, Y
        // and Z coordinates are in the range [-1,1].
        x /= w
        y /= w
        z /= w

        // Clip the point against the near and far clip planes.
        if (z < -1 || z > 1) return false

        // Convert the point from clip coordinate to the range [0,1]. This enables the X and Y coordinates to be
        // converted to screen coordinates, and the Z coordinate to represent a depth value in the range[0,1].
        x = x * 0.5 + 0.5
        y = y * 0.5 + 0.5
        z = z * 0.5 + 0.5

        // Convert the X and Y coordinates from the range [0,1] to screen coordinates.
        x = x * viewport.width + viewport.x
        y = y * viewport.height + viewport.y
        result.x = x
        result.y = y
        result.z = z
        return true
    }

    /**
     * Projects a Cartesian point to screen coordinates, applying an offset to the point's projected depth value. The
     * resultant screen point is in OpenGL screen coordinates, with the origin in the bottom-left corner and axes that
     * extend up and to the right from the origin.
     * <br>
     * This stores the projected point in the result argument, and returns a boolean value indicating whether or not the
     * projection is successful. This returns false if the Cartesian point is clipped by the near clipping plane or the
     * far clipping plane.
     * <br>
     * The depth offset may be any real number and is typically used to move the screenPoint slightly closer to the
     * user's eye in order to give it visual priority over nearby objects or terrain. An offset of zero has no effect.
     * An offset less than zero brings the screenPoint closer to the eye, while an offset greater than zero pushes the
     * projected screen point away from the eye.
     * <br>
     * Applying a non-zero depth offset has no effect on whether the model point is clipped by this method or by WebGL.
     * Clipping is performed on the original model point, ignoring the depth offset. The final depth value after
     * applying the offset is clamped to the range [0,1].
     *
     * @param modelPoint  the Cartesian point to project
     * @param depthOffset the amount of depth offset to apply
     * @param result      a pre-allocated [Vec3] in which to return the projected point
     *
     * @return true if the transformation is successful, otherwise false
     */
    fun projectWithDepth(modelPoint: Vec3, depthOffset: Double, result: Vec3): Boolean {
        // Transform the model point from model coordinates to eye coordinates. The eye coordinate and the clip
        // coordinate are transformed separately in order to reuse the eye coordinate below.
        val mx = modelPoint.x
        val my = modelPoint.y
        val mz = modelPoint.z
        val m = modelview.m
        val ex = m[0] * mx + m[1] * my + m[2] * mz + m[3]
        val ey = m[4] * mx + m[5] * my + m[6] * mz + m[7]
        val ez = m[8] * mx + m[9] * my + m[10] * mz + m[11]
        val ew = m[12] * mx + m[13] * my + m[14] * mz + m[15]

        // Transform the point from eye coordinates to clip coordinates.
        val p = projection.m
        var x = p[0] * ex + p[1] * ey + p[2] * ez + p[3] * ew
        var y = p[4] * ex + p[5] * ey + p[6] * ez + p[7] * ew
        var z = p[8] * ex + p[9] * ey + p[10] * ez + p[11] * ew
        val w = p[12] * ex + p[13] * ey + p[14] * ez + p[15] * ew
        if (w == 0.0) return false

        // Complete the conversion from model coordinates to clip coordinates by dividing by W. The resultant X, Y
        // and Z coordinates are in the range [-1,1].
        x /= w
        y /= w
        z /= w

        // Clip the point against the near and far clip planes.
        if (z < -1 || z > 1) return false

        // Transform the Z eye coordinate to clip coordinates again, this time applying a depth offset. The depth
        // offset is applied only to the matrix element affecting the projected Z coordinate, so we inline the
        // computation here instead of re-computing X, Y, Z and W in order to improve performance. See
        // Matrix4.offsetProjectionDepth for more information on the effect of this offset.
        z = p[8] * ex + p[9] * ey + p[10] * ez * (1 + depthOffset) + p[11] * ew
        z /= w

        // Clamp the point to the near and far clip planes. We know the point's original Z value is contained within
        // the clip planes, so we limit its offset z value to the range [-1, 1] in order to ensure it is not clipped
        // by WebGL. In clip coordinates the near and far clip planes are perpendicular to the Z axis and are
        // located at -1 and 1, respectively.
        z = z.coerceIn(-1.0, 1.0)

        // Convert the point from clip coordinates to the range [0, 1]. This enables the XY coordinates to be
        // converted to screen coordinates, and the Z coordinate to represent a depth value in the range [0, 1].
        x = x * 0.5 + 0.5
        y = y * 0.5 + 0.5
        z = z * 0.5 + 0.5

        // Convert the X and Y coordinates from the range [0,1] to screen coordinates.
        x = x * viewport.width + viewport.x
        y = y * viewport.height + viewport.y
        result.x = x
        result.y = y
        result.z = z
        return true
    }

    /**
     * Converts a geographic [Position] to Cartesian coordinates according to an [altitudeMode].
     * The Cartesian coordinate system is a function of this render context's current globe and its terrain surface,
     * depending on the altitude mode. In general, it is not safe to cache the Cartesian coordinates,
     * as many factors contribute to the value returned, and may change from one frame to the next.
     *
     * @param position     the specified position
     * @param altitudeMode an altitude mode indicating how to interpret the position's altitude component
     * @param result       a pre-allocated [Vec3] in which to store the computed X, Y and Z Cartesian coordinates
     *
     * @return the result argument, set to the computed Cartesian coordinates
     */
    fun geographicToCartesian(
        position: Position, altitudeMode: AltitudeMode, result: Vec3
    ) = geographicToCartesian(position.latitude, position.longitude, position.altitude, altitudeMode, result)

    /**
     * Converts a geographic position to Cartesian coordinates according to an [altitudeMode].
     * The Cartesian coordinate system is a function of this render context's current globe and its terrain surface,
     * depending on the altitude mode. In general, it is not safe to cache the Cartesian coordinates,
     * as many factors contribute to the value returned, and may change from one frame to the next.
     *
     * @param latitude     the position's latitude
     * @param longitude    the position's longitude
     * @param altitude     the position's altitude in meters
     * @param altitudeMode an altitude mode indicating how to interpret the position's altitude component
     * @param result       a pre-allocated [Vec3] in which to store the computed X, Y and Z Cartesian coordinates
     * @param useEM        use the most detailed elevation model data instead of current terrain LoD
     *
     * @return the result argument, set to the computed Cartesian coordinates
     */
    fun geographicToCartesian(
        latitude: Angle, longitude: Angle, altitude: Double, altitudeMode: AltitudeMode, result: Vec3, useEM: Boolean = false
    ): Vec3 {
        when (altitudeMode) {
            ABSOLUTE -> globe.geographicToCartesian(latitude, longitude, altitude, result)
            ABOVE_SEA_LEVEL -> with(globe) {
                geographicToCartesian(latitude, longitude, altitude + geoid.getOffset(latitude, longitude), result)
            }
            CLAMP_TO_GROUND -> if (useEM || !terrain.surfacePoint(latitude, longitude, result)) with(globe) {
                // Use elevation model height as a fallback
                geographicToCartesian(latitude, longitude, getElevation(latitude, longitude), result)
            }
            RELATIVE_TO_GROUND -> if (useEM || terrain.surfacePoint(latitude, longitude, result)) with(globe) {
                if (useEM) geographicToCartesian(latitude, longitude, getElevation(latitude, longitude), result)
                // Offset along the normal vector at the terrain surface point.
                if (altitude != 0.0) geographicToCartesianNormal(latitude, longitude, scratchVector).also {
                    result.add(scratchVector.multiply(altitude * verticalExaggeration))
                }
            } else with(globe) {
                // Use elevation model height as a fallback
                geographicToCartesian(latitude, longitude, altitude + getElevation(latitude, longitude), result)
            }
        }
        return result
    }

    /**
     * Per-WorldWindow shader programs. Kept out of the shared [renderResourceCache] so each
     * WorldWindow owns its own program object - GL uniform values are per-context, so a
     * shared Kotlin program would have its `loadX` cache fields clobbered across windows.
     */
    private val shaderPrograms = HashMap<KClass<*>, AbstractShaderProgram>()

    @Suppress("UNCHECKED_CAST")
    fun <P: AbstractShaderProgram> getShaderProgram(key: KClass<P>, builder: () -> P): P =
        (shaderPrograms[key] ?: builder().also { shaderPrograms[key] = it }) as P

    inline fun <reified P : AbstractShaderProgram> getShaderProgram(noinline create: () -> P): P =
        getShaderProgram(P::class, create)

    fun getTexture(imageSource: ImageSource, imageOptions: ImageOptions? = null, retrieve: Boolean = true) =
        renderResourceCache.run { get(imageSource) ?: if (retrieve) retrieveTexture(imageSource, imageOptions) else null } as Texture?

    fun getBufferObject(key: Any, builder: () -> BufferObject) = renderResourceCache.run { get(key) ?: builder().also { put(key, it, bufferGpuFootprint(it.byteCount)) } } as BufferObject

    fun getText(text: String?, attributes: TextAttributes, render: Boolean = true) = renderResourceCache.run {
        scratchTextCacheKey.text = text
        scratchTextCacheKey.attributes = attributes
        // Use scratch key on get operation to avoid unnecessary object creation on each text render on each frame
        get(scratchTextCacheKey) as Texture? ?: if (render) textRenderer.renderText(text, attributes)?.also {
            // Use new text cache key and copy attributes on put operation to avoid cache issues on attributes modification
            put(TextCacheKey(text, TextAttributes(attributes)), it, it.byteCount)
        } else null
    }

    /** Queue a buffer upload when the cached [BufferObject]'s version trails [newVersion].
     *  [onUploaded] fires exactly once — async after the GL write, or sync here when no
     *  upload was queued. Pass nothing to skip; `noinline` is allocation-free at null. */
    inline fun offerGLBufferUpload(
        key: Any,
        newVersion: Int,
        noinline onUploaded: (() -> Unit)? = null,
        arrayBuilder: () -> NumericArray,
    ) {
        val buffer = renderResourceCache[key] as? BufferObject
        if (buffer != null && buffer.version < newVersion) {
            val array = arrayBuilder()
            uploadQueue?.queueBufferUpload(buffer, array, newVersion, onUploaded)
            renderResourceCache.updateSize(key, bufferGpuFootprint(array.byteCount))
        } else {
            onUploaded?.invoke()
        }
    }

    fun offerBackgroundDrawable(drawable: Drawable) {
        drawableQueue?.offerDrawable(drawable, DrawableGroup.BACKGROUND, 0.0)
    }

    fun offerSurfaceDrawable(drawable: Drawable, zOrder: Double) {
        contributeShadowSceneBounds(drawable)
        drawableQueue?.offerDrawable(drawable, DrawableGroup.SURFACE, zOrder)
    }

    fun offerShapeDrawable(drawable: Drawable, cameraDistanceSq: Double) {
        contributeShadowSceneBounds(drawable)
        // order by descending squared distance to the viewer
        drawableQueue?.offerDrawable(drawable, DrawableGroup.SHAPE, -cameraDistanceSq)
    }

    /**
     * Accumulates the drawable's world bounding sphere into this frame's [ShadowSceneBounds]
     * when a shadow layer is active. [earth.worldwind.layer.shadow.ShadowLayer] consumes the
     * accumulation on the next frame to fit cascade splits to the content actually in view.
     */
    /** True when a shadow-casting bounding sphere outside the view frustum still intersects
     *  a valid cascade's light-space box - its shadow can reach visible ground. Requires the
     *  shadow layer to have rendered earlier in the layer list ([shadowState] set).
     *  Only the first [ShadowState.offscreenCasterCascades] cascades recruit (app-tunable via
     *  [earth.worldwind.layer.shadow.ShadowLayer.offscreenCasterCascades]): the coarse
     *  cascades' texels span metres, so an off-screen caster's shadow there is sub-texel
     *  noise, and their huge light boxes would keep distant content alive wholesale.
     *  Visible casters still draw into every cascade. */
    fun intersectsShadowCasterRegion(center: Vec3, radius: Double): Boolean {
        val state = shadowState ?: return false
        for (i in 0 until minOf(state.cascadeCount, state.offscreenCasterCascades)) {
            val cascade = state.cascades[i]
            if (cascade.isValid && cascade.intersectsSphere(center, radius)) return true
        }
        return false
    }

    private fun contributeShadowSceneBounds(drawable: Drawable) {
        if (!hasShadowLayer || isPickMode) return
        if (drawable !is ShadowCaster) return
        val center = drawable.shadowCasterCenter ?: return
        // View-forward distance to the sphere center. Camera forward = -(third modelview row).
        val m = modelview.m
        val distance = -(m[8] * (center.x - cameraPoint.x)
            + m[9] * (center.y - cameraPoint.y)
            + m[10] * (center.z - cameraPoint.z))
        // lightDirection is resolved by WorldWind before any layer renders. The
        // overflow-fallback caster top is CAMERA-RELATIVE: the shadow layer re-bases it with
        // its own anchored sun, and at absolute ECEF magnitudes even a sub-milliradian
        // difference between the continuous and anchored directions is kilometres of error.
        val lightZTop = lightDirection.x * (center.x - cameraPoint.x) +
            lightDirection.y * (center.y - cameraPoint.y) +
            lightDirection.z * (center.z - cameraPoint.z) + drawable.shadowCasterRadius
        shadowSceneBoundsCurrent.contribute(distance, drawable.shadowCasterRadius, lightZTop)
        // Track individual spheres only for ELEVATED casters - content at/below camera level
        // is already covered by each cascade's slice pullback, and registering every tile
        // mesh would overflow the list in city scenes, degrading to the global fallback in
        // exactly the drone-over-city case the per-cascade gating exists for.
        if (lightZTop > ShadowSceneBounds.ELEVATED_CASTER_THRESHOLD) {
            shadowSceneBoundsCurrent.addCasterSphere(center.x, center.y, center.z, drawable.shadowCasterRadius)
        }
    }

    fun offerScreenDrawable(drawable: Drawable, zOrder: Double) {
        drawableQueue?.offerDrawable(drawable, DrawableGroup.SCREEN, zOrder)
    }

    fun offerDrawableTerrain(drawable: DrawableTerrain, sortOrder: Double) {
        drawableTerrain?.offerDrawable(drawable, DrawableGroup.SURFACE, sortOrder)
    }

    fun sortDrawables() {
        drawableQueue?.sortDrawables()
        drawableTerrain?.sortDrawables()
    }

    val drawableCount get() = drawableQueue?.count ?: 0

    @Suppress("UNCHECKED_CAST")
    fun <T : Drawable> getDrawablePool(key: KClass<T>): Pool<T> {
        // use SynchronizedPool; acquire and are release may be called in separate threads
        return drawablePools[key] as? Pool<T> ?: SynchronizedPool<T>().also { drawablePools[key] = it }
    }

    fun offerPickedObject(pickedObject: PickedObject) { pickedObjects?.offerPickedObject(pickedObject) }

    fun nextPickedObjectId(): Int {
        if (++pickedObjectId > MAX_PICKED_OBJECT_ID) pickedObjectId = 1
        return pickedObjectId
    }

    @Suppress("UNCHECKED_CAST")
    fun <T> getUserProperty(key: Any) = userProperties[key] as? T

    fun putUserProperty(key: Any, value: Any) = userProperties.put(key, value)

    fun removeUserProperty(key: Any) = userProperties.remove(key)

    fun hasUserProperty(key: Any) = userProperties.containsKey(key)

    protected data class TextCacheKey(
        var text: String? = null,
        var attributes: TextAttributes? = null
    )
}