package earth.worldwind.formats.gltf

import earth.worldwind.formats.BinaryDataView

/**
 * Reads a glTF 2.0 binary container (GLB) blob into its JSON chunk + BIN chunk. The format:
 *
 * ```
 * Bytes 0..3   : magic = "glTF" (0x46546C67)
 * Bytes 4..7   : version (uint32 LE) = 2
 * Bytes 8..11  : byteLength (uint32 LE)
 * Then N chunks, each:
 *   chunkLength (uint32 LE)
 *   chunkType (4 bytes ASCII; "JSON" = 0x4E4F534A, "BIN\0" = 0x004E4942)
 *   chunkData (chunkLength bytes)
 * ```
 *
 * The first chunk is always JSON; the second (when present) is BIN. Any further chunks are
 * extensions and ignored.
 *
 * Throws [IllegalArgumentException] on a structural mismatch — callers (the b3dm/i3dm
 * loaders, the 3D Tiles 1.1 GLB content path) translate that into a logged failure on the
 * tile.
 */
object GlbReader {
    private const val GLB_MAGIC = 0x46546C67  // "glTF" little-endian
    private const val CHUNK_TYPE_JSON = 0x4E4F534A  // "JSON" little-endian
    private const val CHUNK_TYPE_BIN = 0x004E4942  // "BIN\0" little-endian

    /**
     * Decoded GLB payload. [binChunk] is null when the asset has no BIN chunk (rare — only
     * happens for JSON-only assets that reference external buffers via URI, which we don't
     * support inside 3D Tiles content).
     */
    class Decoded internal constructor(
        val jsonText: String,
        val binChunk: ByteArray?,
    )

    /**
     * @param bytes the GLB blob — typically the tail of a b3dm payload after the feature +
     *   batch tables, or a standalone .glb fetched via the 3D Tiles 1.1 content path.
     * @param offset start of the GLB inside [bytes]. Default 0.
     * @param length length of the GLB inside [bytes]. Default `bytes.size - offset`.
     */
    fun parse(bytes: ByteArray, offset: Int = 0, length: Int = bytes.size - offset): Decoded {
        require(length >= 12) { "GLB too short: length=$length (need at least 12 for the header)" }
        require(offset + length <= bytes.size) {
            "GLB length $length exceeds backing array (offset=$offset, size=${bytes.size})"
        }
        val view = BinaryDataView(bytes)
        val magic = view.getInt32(offset, littleEndian = true)
        require(magic == GLB_MAGIC) {
            "GLB magic mismatch: expected 0x46546C67 (\"glTF\"), got 0x" +
                magic.toUInt().toString(16).padStart(8, '0')
        }
        val version = view.getInt32(offset + 4, littleEndian = true)
        require(version == 2) { "GLB version mismatch: expected 2, got $version" }
        val totalLength = view.getInt32(offset + 8, littleEndian = true)
        require(totalLength in 12..length) {
            "GLB totalLength $totalLength out of range (chunk=$length)"
        }

        var jsonText: String? = null
        var binChunk: ByteArray? = null
        var cursor = offset + 12
        while (cursor < offset + totalLength) {
            require(cursor + 8 <= offset + totalLength) {
                "GLB chunk header truncated at offset $cursor"
            }
            val chunkLength = view.getInt32(cursor, littleEndian = true)
            val chunkType = view.getInt32(cursor + 4, littleEndian = true)
            val dataStart = cursor + 8
            val dataEnd = dataStart + chunkLength
            require(dataEnd <= offset + totalLength) {
                "GLB chunk payload truncated: type=0x${chunkType.toUInt().toString(16)} " +
                    "length=$chunkLength but only ${offset + totalLength - dataStart} bytes remain"
            }
            when (chunkType) {
                CHUNK_TYPE_JSON -> {
                    // JSON chunk is space-padded by spec; trimEnd cleans that up before parse.
                    jsonText = bytes.decodeToString(dataStart, dataEnd).trimEnd(' ', '�')
                }
                CHUNK_TYPE_BIN -> {
                    // Slice into the chunk; sliceArray copies, which is fine — readers index
                    // off the slice with offset 0 and we don't pay for the copy across the
                    // full payload (only the BIN chunk, which is usually the bulk).
                    binChunk = bytes.sliceArray(dataStart until dataEnd)
                }
                // Other chunk types are extensions per the glTF 2.0 spec; skip silently.
            }
            cursor = dataEnd
        }
        return Decoded(
            jsonText = jsonText ?: error("GLB has no JSON chunk"),
            binChunk = binChunk,
        )
    }
}
