package earth.worldwind.globe.elevation.coverage

import earth.worldwind.WorldWind
import earth.worldwind.geom.Angle
import earth.worldwind.geom.Sector
import earth.worldwind.geom.TileMatrix
import earth.worldwind.geom.TileMatrixSet
import earth.worldwind.globe.elevation.CacheReadableElevationSourceFactory
import earth.worldwind.globe.elevation.ElevationSourceFactory
import earth.worldwind.globe.elevation.coverage.ElevationCoverage.Companion.MISSING_DATA
import earth.worldwind.layer.cache.RevalidatingSource
import earth.worldwind.util.AbsentResourceList
import earth.worldwind.util.Logger.INFO
import earth.worldwind.util.Logger.log
import earth.worldwind.util.LongLruMemoryCache
import earth.worldwind.util.RetrievalLane
import earth.worldwind.util.RetrievalLanes
import earth.worldwind.util.RetrievalPhase
import earth.worldwind.util.SynchronizedList
import earth.worldwind.util.format.format
import earth.worldwind.util.math.fract
import earth.worldwind.util.math.mod
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.cancelChildren
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlin.coroutines.cancellation.CancellationException
import kotlin.time.Duration.Companion.seconds

abstract class AbstractTiledElevationCoverage(
    tileMatrixSet: TileMatrixSet, elevationSourceFactory: ElevationSourceFactory
): AbstractElevationCoverage() {
    companion object {
        protected const val GET_HEIGHT_LIMIT_SAMPLES = 32
        protected const val NO_DATA = Short.MIN_VALUE
        protected const val ALMOST_ONE = 0.9999999999999999
    }

    var tileMatrixSet = tileMatrixSet
        set(value) {
            field = value
            sector.copy(value.sector) // Use TMS sector as bounding sector by default
            clear()
        }
    var elevationSourceFactory = elevationSourceFactory
        set(value) {
            (field as? RevalidatingSource)?.onTileRevalidated = null
            field = value
            wireRevalidation(value)
            clear()
        }

    // Tile keys (matrix.tileKey) a stale-while-revalidate refresh re-cached, enqueued off the
    // render thread and drained on it (see fetchTileArray) to drop the stale in-memory array so
    // the tessellator re-reads the fresh tile. SynchronizedList keeps the cross-thread hand-off safe.
    private val pendingRevalidations = SynchronizedList<Long>()

    init { wireRevalidation(elevationSourceFactory) }

    /** Wire a [RevalidatingSource] factory's refresh callback to drop the tile's cached array
     *  and redraw. No-op for factories that don't support revalidation. */
    private fun wireRevalidation(factory: ElevationSourceFactory) {
        (factory as? RevalidatingSource)?.onTileRevalidated = { z, column, row ->
            tileMatrixSet.entries.getOrNull(z)?.let { matrix ->
                pendingRevalidations.add(matrix.tileKey(row, column))
                updateTimestamp(matrix.tileSector(row, column))
                WorldWind.requestRedraw()
            }
        }
    }
    /**
     * Unique identifier of the coverage type, defined by elevation source factory content type
     */
    val type get() = elevationSourceFactory.contentType
    /**
     * Controls how many concurrent tile requests are allowed for this coverage.
     */
    var retrievalQueueSize = 4
    /**
     * Concurrent cache-only reads allowed. Generous vs [retrievalQueueSize]: cache reads are
     * cheap local I/O and must get their own budget separate from the network-retrieval budget,
     * so a slow network DEM fetch holding the network slots can't stall cached tiles behind it.
     */
    var cacheRetrievalQueueSize = 16
    /**
     * Shared lane bookkeeping (network lane = [retrievalQueueSize], cache lane =
     * [cacheRetrievalQueueSize], plus the "cache already missed" set so a tile waiting on a full
     * network lane doesn't re-read the cache every frame). The same helper backs the image
     * [earth.worldwind.render.RenderResourceCache]; here it is keyed by tile [Long].
     */
    protected val lanes = RetrievalLanes<Long>()
    protected var coverageCache = LongLruMemoryCache<ElevationImage>(1024 * 1024 * 64)
    protected var isRetrievalEnabled = false
    protected val absentResourceList = AbsentResourceList<Long>(3, 5.seconds)
    protected val mainScope = MainScope()

    init {
        sector.copy(tileMatrixSet.sector) // Use TMS sector as bounding sector by default
        log(INFO, "Coverage cache initialized %.0f KB".format(coverageCache.capacity / 1024.0))
    }

    /**
     * Setup custom coverage cache size according to device capabilities and user needs.
     */
    fun setupCoverageCache(capacity: Long, lowWater: Long = (capacity * 0.75).toLong()) {
        coverageCache = LongLruMemoryCache(capacity, lowWater)
    }

    override fun clear() {
        mainScope.coroutineContext.cancelChildren() // Cancel all async jobs but keep scope reusable
        lanes.clear()
        coverageCache.clear()
        absentResourceList.clear()
        updateTimestamp()
    }

    override fun doGetElevation(latitude: Angle, longitude: Angle, retrieve: Boolean): Float {
        if (!tileMatrixSet.sector.contains(latitude, longitude)) return MISSING_DATA // no coverage in the specified location
        val targetIdx = tileMatrixSet.entries.size - 1 // retrieve height from last available matrix
        for (idx in targetIdx downTo 0) {
            // enable retrieval of the last and the first matrix
            isRetrievalEnabled = retrieve && (idx == targetIdx || idx == 0)
            val tileMatrix = tileMatrixSet.entries[idx]
            val sector = tileMatrix.sector
            val deltaLat = sector.deltaLatitude.inDegrees / tileMatrix.matrixHeight
            val deltaLon = sector.deltaLongitude.inDegrees / tileMatrix.matrixWidth
            val row = ((sector.maxLatitude.inDegrees - latitude.inDegrees) / deltaLat).toInt()
            val col = ((longitude.inDegrees - sector.minLongitude.inDegrees) / deltaLon).toInt()
            fetchTileArray(tileMatrix, row, col)?.let {
                val maxLat = sector.maxLatitude.inDegrees - deltaLat * row
                val minLon = sector.minLongitude.inDegrees + deltaLon * col
                val maxX = tileMatrix.tileWidth - 1
                val maxY = tileMatrix.tileHeight - 1
                val x = (maxX * (longitude.inDegrees - minLon) / deltaLon).toFloat()
                val y = (maxY * (maxLat - latitude.inDegrees) / deltaLat).toFloat()
                val x0 = x.toInt().coerceIn(0, maxX)
                val x1 = (x0 + 1).coerceIn(0, maxX)
                val y0 = y.toInt().coerceIn(0, maxY)
                val y1 = (y0 + 1).coerceIn(0, maxY)
                val x0y0 = it[x0 + y0 * tileMatrix.tileWidth]
                val x1y0 = it[x1 + y0 * tileMatrix.tileWidth]
                val x0y1 = it[x0 + y1 * tileMatrix.tileWidth]
                val x1y1 = it[x1 + y1 * tileMatrix.tileWidth]
                if (x0y0 == NO_DATA || x1y0 == NO_DATA || x0y1 == NO_DATA || x1y1 == NO_DATA) return MISSING_DATA
                val xf = x - x0
                val yf = y - y0
                return (1 - xf) * (1 - yf) * x0y0 + xf * (1 - yf) * x1y0 + (1 - xf) * yf * x0y1 + xf * yf * x1y1
            }
        }
        return MISSING_DATA // did not find a tile
    }

    override fun doGetElevationGrid(gridSector: Sector, gridWidth: Int, gridHeight: Int, result: FloatArray) {
        if (!tileMatrixSet.sector.intersects(gridSector)) return  // no coverage in the specified sector
        val targetPixelSpan = gridSector.deltaLatitude.div(gridHeight)
        val targetIdx = tileMatrixSet.indexOfMatrixNearest(targetPixelSpan)
        val tileBlock = TileBlock()
        for (idx in targetIdx downTo 0) {
            // enable retrieval of the target matrix and the first matrix
            isRetrievalEnabled = idx == targetIdx || idx == 0
            val tileMatrix = tileMatrixSet.entries[idx]
            if (fetchTileBlock(gridSector, gridWidth, gridHeight, tileMatrix, tileBlock)) {
                readHeightGrid(gridSector, gridWidth, gridHeight, tileBlock, result)
                return
            }
        }
    }

    override fun doGetElevationLimits(sector: Sector, result: FloatArray) {
        if (!tileMatrixSet.sector.intersects(sector)) return  // no coverage in the specified sector
        val targetPixelSpan = sector.deltaLatitude.div(GET_HEIGHT_LIMIT_SAMPLES)
        val targetIdx = tileMatrixSet.indexOfMatrixNearest(targetPixelSpan)
        val tileBlock = TileBlock()
        for (idx in targetIdx downTo 0) {
            // enable retrieval of the target matrix and the first matrix
            isRetrievalEnabled = idx == targetIdx || idx == 0
            val tileMatrix = tileMatrixSet.entries[idx]
            if (fetchTileBlock(sector, tileMatrix, tileBlock)) {
                scanHeightLimits(sector, tileBlock, result)
                return
            }
        }
    }

    protected open fun fetchTileBlock(
        gridSector: Sector, gridWidth: Int, gridHeight: Int, tileMatrix: TileMatrix, result: TileBlock
    ): Boolean {
        val tileWidth = tileMatrix.tileWidth
        val tileHeight = tileMatrix.tileHeight
        val rasterWidth = tileMatrix.matrixWidth * tileWidth
        val rasterHeight = tileMatrix.matrixHeight * tileHeight
        val matrixMinLat = tileMatrix.sector.minLatitude.inDegrees
        val matrixMaxLat = tileMatrix.sector.maxLatitude.inDegrees
        val matrixMinLon = tileMatrix.sector.minLongitude.inDegrees
        val matrixMaxLon = tileMatrix.sector.maxLongitude.inDegrees
        val matrixDeltaLat = tileMatrix.sector.deltaLatitude.inDegrees
        val matrixDeltaLon = tileMatrix.sector.deltaLongitude.inDegrees
        val sMin = 1.0 / (2.0 * rasterWidth)
        val sMax = 1.0 - sMin
        val tMin = 1.0 / (2.0 * rasterHeight)
        val tMax = 1.0 - tMin
        result.tileMatrix = tileMatrix
        result.clear()
        var lon = gridSector.minLongitude.inDegrees
        val deltaLon = gridSector.deltaLongitude.inDegrees / (gridWidth - 1)
        var uIdx = 0
        while (uIdx < gridWidth) {
            // explicitly set the last lon to the max longitude to ensure alignment
            if (uIdx == gridWidth - 1) lon = gridSector.maxLongitude.inDegrees
            if (lon in matrixMinLon..matrixMaxLon) {
                val s = (lon - matrixMinLon) / matrixDeltaLon
                var u: Double
                var i0: Int
                var i1: Int
                if (tileMatrix.sector.isFullSphere) {
                    u = rasterWidth * fract(s) // wrap the horizontal coordinate
                    i0 = mod((u - 0.5).toInt(), rasterWidth)
                    i1 = mod(i0 + 1, rasterWidth)
                } else {
                    u = rasterWidth * s.coerceIn(sMin, sMax) // clamp the horizontal coordinate
                    i0 = (u - 0.5).toInt().coerceIn(0, rasterWidth - 1)
                    i1 = (i0 + 1).coerceIn(0, rasterWidth - 1)
                }
                val col0 = i0 / tileWidth
                val col1 = i1 / tileWidth
                result.cols[col0] = 0
                result.cols[col1] = 0
            }
            uIdx++
            lon += deltaLon
        }
        var lat = gridSector.minLatitude.inDegrees
        val deltaLat = gridSector.deltaLatitude.inDegrees / (gridHeight - 1)
        var vIdx = 0
        while (vIdx < gridHeight) {
            // explicitly set the last lat to the max latitude to ensure alignment
            if (vIdx == gridHeight - 1) lat = gridSector.maxLatitude.inDegrees
            if (lat in matrixMinLat..matrixMaxLat) {
                val t = (matrixMaxLat - lat) / matrixDeltaLat
                val v = rasterHeight * t.coerceIn(tMin, tMax) // clamp the vertical coordinate to the raster edge
                val j0 = (v - 0.5).toInt().coerceIn(0, rasterHeight - 1)
                val j1 = (j0 + 1).coerceIn(0, rasterHeight - 1)
                val row0 = j0 / tileHeight
                val row1 = j1 / tileHeight
                result.rows[row0] = 0
                result.rows[row1] = 0
            }
            vIdx++
            lat += deltaLat
        }
        for (row in result.rows.keys) {
            for (col in result.cols.keys) {
                val image = fetchTileImage(tileMatrix, row, col)
                if (image != null) result.putTileImage(row, col, image) else return false
            }
        }
        return true
    }

    protected open fun fetchTileBlock(sector: Sector, tileMatrix: TileMatrix, result: TileBlock): Boolean {
        val tileWidth = tileMatrix.tileWidth
        val tileHeight = tileMatrix.tileHeight
        val rasterWidth = tileMatrix.matrixWidth * tileWidth
        val rasterHeight = tileMatrix.matrixHeight * tileHeight
        val matrixMaxLat = tileMatrix.sector.maxLatitude.inDegrees
        val matrixMinLon = tileMatrix.sector.minLongitude.inDegrees
        val matrixDeltaLat = tileMatrix.sector.deltaLatitude.inDegrees
        val matrixDeltaLon = tileMatrix.sector.deltaLongitude.inDegrees
        val intersection = Sector(tileMatrix.sector)
        intersection.intersect(sector)
        val sMin = (intersection.minLongitude.inDegrees - matrixMinLon) / matrixDeltaLon
        val sMax = (intersection.maxLongitude.inDegrees - matrixMinLon) / matrixDeltaLon
        val uMin = (rasterWidth * sMin).toInt()
        val uMax = (rasterWidth * sMax + ALMOST_ONE).toInt()
        val iMin = uMin.coerceIn(0, rasterWidth - 1)
        val iMax = uMax.coerceIn(0, rasterWidth - 1)
        val colMin = iMin / tileWidth
        val colMax = iMax / tileWidth
        val tMin = (matrixMaxLat - intersection.maxLatitude.inDegrees) / matrixDeltaLat
        val tMax = (matrixMaxLat - intersection.minLatitude.inDegrees) / matrixDeltaLat
        val vMin = (rasterHeight * tMin).toInt()
        val vMax = (rasterHeight * tMax + ALMOST_ONE).toInt()
        val jMin = vMin.coerceIn(0, rasterHeight - 1)
        val jMax = vMax.coerceIn(0, rasterHeight - 1)
        val rowMin = jMin / tileHeight
        val rowMax = jMax / tileHeight
        result.tileMatrix = tileMatrix
        result.clear()
        for (row in rowMin..rowMax) {
            for (col in colMin..colMax) {
                val image = fetchTileImage(tileMatrix, row, col)
                if (image != null) {
                    result.rows[row] = 0
                    result.cols[col] = 0
                    result.putTileImage(row, col, image)
                } else return false
            }
        }
        return true
    }

    /** Render-thread drain: drop in-memory arrays for tiles a background refresh re-cached and
     *  un-mark them as cache-checked, so the next fetch re-reads the fresh tile from the store. */
    private fun drainRevalidations() {
        while (pendingRevalidations.isNotEmpty()) {
            val key = pendingRevalidations.removeAt(0)
            coverageCache.remove(key)
            lanes.unmarkChecked(key)
        }
    }

    protected open fun fetchTileArray(tileMatrix: TileMatrix, row: Int, column: Int): ShortArray? =
        fetchTileImage(tileMatrix, row, column)?.array

    protected open fun fetchTileImage(tileMatrix: TileMatrix, row: Int, column: Int): ElevationImage? {
        drainRevalidations()
        val key = tileMatrix.tileKey(row, column)
        return coverageCache[key] ?: run {
            if (isRetrievalEnabled) {
                val cacheFactory = elevationSourceFactory as? CacheReadableElevationSourceFactory
                val isAbsent = absentResourceList.isResourceAbsent(key)
                // Cache-backed factories plan cache-vs-network; a plain network factory skips the
                // cache phase entirely (no cache to read), going straight to the network lane.
                val phase = if (cacheFactory != null) lanes.planNetworkBound(key, isAbsent)
                    else if (isAbsent || lanes.isNetworkInFlight(key)) RetrievalPhase.NONE else RetrievalPhase.NETWORK
                when (phase) {
                    RetrievalPhase.NONE -> {}
                    // Phase 1: cache-only read on its own (generous) budget, so a slow network DEM
                    // fetch holding the network slots can't stall cached tiles behind it. A hit
                    // renders next frame; a miss falls through to the online request in the same
                    // coroutine (moving over to the network lane), so the tile can never strand
                    // waiting for a launch that no future query would re-issue.
                    RetrievalPhase.CACHE -> if (lanes.canReserve(RetrievalLane.LOCAL, cacheRetrievalQueueSize, key)) {
                        lanes.reserve(RetrievalLane.LOCAL, key)
                        mainScope.launch {
                            val cached = try {
                                cacheFactory!!.readCachedTileImage(tileMatrix, row, column)
                            } catch (e: CancellationException) {
                                throw e
                            } catch (e: Throwable) {
                                null // ignore cache read failures and fall through to the network
                            } finally {
                                lanes.release(RetrievalLane.LOCAL, key)
                            }
                            if (cached != null) retrievalSucceeded(key, cached) else {
                                lanes.markChecked(key) // route straight to the network lane if re-fetched later
                                // Guaranteed continuation of a confirmed cache miss: reserve past the
                                // network lane budget rather than drop the request.
                                lanes.reserve(RetrievalLane.REMOTE, key)
                                try {
                                    retrieveTileArray(key, tileMatrix, row, column)
                                } catch (e: CancellationException) {
                                    throw e
                                } catch (e: Throwable) {
                                    retrievalFailed(key)
                                }
                            }
                        }
                    }
                    // Phase 2: network retrieval — cache miss already confirmed, or the factory
                    // isn't cache-backed. Throttled by [retrievalQueueSize].
                    RetrievalPhase.NETWORK -> launchNetworkRetrieve(key, tileMatrix, row, column)
                }
            }
            null
        }
    }

    protected abstract suspend fun retrieveTileArray(key: Long, tileMatrix: TileMatrix, row: Int, column: Int)

    /** Phase 2: launch the throttled network retrieve for one tile, if the network lane has budget. */
    private fun launchNetworkRetrieve(key: Long, tileMatrix: TileMatrix, row: Int, column: Int) {
        if (lanes.canReserve(RetrievalLane.REMOTE, retrievalQueueSize, key)) {
            lanes.reserve(RetrievalLane.REMOTE, key)
            mainScope.launch {
                try {
                    retrieveTileArray(key, tileMatrix, row, column)
                } catch (e: CancellationException) {
                    throw e
                } catch (e: Throwable) {
                    retrievalFailed(key)
                }
            }
        }
    }

    /**
     * Builds the tile image (full-grid min/max/missing scan) off the render thread. The decode itself
     * already runs off-thread, but its continuation resumes on Main; a startup burst of completed tiles
     * would otherwise stack ~1 ms/tile of scanning onto the render-critical main thread. Call this from
     * the retrieval coroutine, then hand the ready image to [retrievalSucceeded] (cheap, Main-thread).
     */
    protected suspend fun buildImage(value: ShortArray) = withContext(Dispatchers.Default) { ElevationImage(value) }

    protected fun retrievalSucceeded(key: Long, image: ElevationImage) {
        coverageCache.put(key, image, image.sizeInBytes)
        absentResourceList.unmarkResourceAbsent(key)
        lanes.release(RetrievalLane.REMOTE, key) // no-op on the cache-hit path (key was on the local lane)
        lanes.unmarkChecked(key) // re-check the cache if this tile is fetched again after eviction
        // Decode the tile sector back from the key so consumers outside it keep their cached height limits
        val matrix = tileMatrixSet.entries.getOrNull((key ushr 56).toInt())
        if (matrix != null) {
            updateTimestamp(matrix.tileSector((key ushr 28 and 0xFFFFFFFL).toInt(), (key and 0xFFFFFFFL).toInt()))
        } else updateTimestamp()
        WorldWind.requestRedraw()
    }

    protected fun retrievalFailed(key: Long) {
        absentResourceList.markResourceAbsent(key)
        lanes.release(RetrievalLane.REMOTE, key)
    }

    protected open fun readHeightGrid(
        gridSector: Sector, gridWidth: Int, gridHeight: Int, tileBlock: TileBlock, result: FloatArray
    ) {
        val tileWidth = tileBlock.tileMatrix.tileWidth
        val tileHeight = tileBlock.tileMatrix.tileHeight
        val rasterWidth = tileBlock.tileMatrix.matrixWidth * tileWidth
        val rasterHeight = tileBlock.tileMatrix.matrixHeight * tileHeight
        val matrixMinLat = tileBlock.tileMatrix.sector.minLatitude.inDegrees
        val matrixMaxLat = tileBlock.tileMatrix.sector.maxLatitude.inDegrees
        val matrixMinLon = tileBlock.tileMatrix.sector.minLongitude.inDegrees
        val matrixMaxLon = tileBlock.tileMatrix.sector.maxLongitude.inDegrees
        val matrixDeltaLat = tileBlock.tileMatrix.sector.deltaLatitude.inDegrees
        val matrixDeltaLon = tileBlock.tileMatrix.sector.deltaLongitude.inDegrees
        val sMin = 1.0 / (2.0 * rasterWidth)
        val sMax = 1.0 - sMin
        val tMin = 1.0 / (2.0 * rasterHeight)
        val tMax = 1.0 - tMin
        var rIdx = 0
        var lat = gridSector.minLatitude.inDegrees
        val deltaLat = gridSector.deltaLatitude.inDegrees / (gridHeight - 1)
        var hIdx = 0
        while (hIdx < gridHeight) {
            // explicitly set the last lat to the max latitude to ensure alignment
            if (hIdx == gridHeight - 1) lat = gridSector.maxLatitude.inDegrees
            val t = (matrixMaxLat - lat) / matrixDeltaLat
            val v = rasterHeight * t.coerceIn(tMin, tMax) // clamp the vertical coordinate to the raster edge
            val b = fract(v - 0.5).toFloat()
            val j0 = (v - 0.5).toInt().coerceIn(0, rasterHeight - 1)
            val j1 = (j0 + 1).coerceIn(0, rasterHeight - 1)
            val row0 = j0 / tileHeight
            val row1 = j1 / tileHeight
            var lon = gridSector.minLongitude.inDegrees
            val deltaLon = gridSector.deltaLongitude.inDegrees / (gridWidth - 1)
            var wIdx = 0
            while (wIdx < gridWidth) {
                // explicitly set the last lon to the max longitude to ensure alignment
                if (wIdx == gridWidth - 1) lon = gridSector.maxLongitude.inDegrees
                val s = (lon - matrixMinLon) / matrixDeltaLon
                var u: Double
                var i0: Int
                var i1: Int
                if (tileBlock.tileMatrix.sector.isFullSphere) {
                    u = rasterWidth * fract(s) // wrap the horizontal coordinate
                    i0 = mod((u - 0.5).toInt(), rasterWidth)
                    i1 = mod(i0 + 1, rasterWidth)
                } else {
                    u = rasterWidth * s.coerceIn(sMin, sMax) // clamp the horizontal coordinate
                    i0 = (u - 0.5).toInt().coerceIn(0, rasterWidth - 1)
                    i1 = (i0 + 1).coerceIn(0, rasterWidth - 1)
                }
                val a = fract(u - 0.5).toFloat()
                val col0 = i0 / tileWidth
                val col1 = i1 / tileWidth
                if (lat in matrixMinLat..matrixMaxLat && lon in matrixMinLon..matrixMaxLon) {
                    val i0j0 = tileBlock.readTexel(row0, col0, i0 % tileWidth, j0 % tileHeight)
                    val i1j0 = tileBlock.readTexel(row0, col1, i1 % tileWidth, j0 % tileHeight)
                    val i0j1 = tileBlock.readTexel(row1, col0, i0 % tileWidth, j1 % tileHeight)
                    val i1j1 = tileBlock.readTexel(row1, col1, i1 % tileWidth, j1 % tileHeight)
                    if (i0j0 != NO_DATA && i1j0 != NO_DATA && i0j1 != NO_DATA && i1j1 != NO_DATA) {
                        result[rIdx] = (1 - a) * (1 - b) * i0j0 + a * (1 - b) * i1j0 + (1 - a) * b * i0j1 + a * b * i1j1
                    }
                }
                rIdx++
                wIdx++
                lon += deltaLon
            }
            hIdx++
            lat += deltaLat
        }
    }

    protected open fun scanHeightLimits(sector: Sector, tileBlock: TileBlock, result: FloatArray) {
        val tileWidth = tileBlock.tileMatrix.tileWidth
        val tileHeight = tileBlock.tileMatrix.tileHeight
        val rasterWidth = tileBlock.tileMatrix.matrixWidth * tileWidth
        val rasterHeight = tileBlock.tileMatrix.matrixHeight * tileHeight
        val matrixMaxLat = tileBlock.tileMatrix.sector.maxLatitude.inDegrees
        val matrixMinLon = tileBlock.tileMatrix.sector.minLongitude.inDegrees
        val matrixDeltaLat = tileBlock.tileMatrix.sector.deltaLatitude.inDegrees
        val matrixDeltaLon = tileBlock.tileMatrix.sector.deltaLongitude.inDegrees
        val intersection = Sector(tileBlock.tileMatrix.sector)
        intersection.intersect(sector)
        val sMin = (intersection.minLongitude.inDegrees - matrixMinLon) / matrixDeltaLon
        val sMax = (intersection.maxLongitude.inDegrees - matrixMinLon) / matrixDeltaLon
        val uMin = (rasterWidth * sMin).toInt()
        val uMax = (rasterWidth * sMax + ALMOST_ONE).toInt()
        val iMin = uMin.coerceIn(0, rasterWidth - 1)
        val iMax = uMax.coerceIn(0, rasterWidth - 1)
        val tMin = (matrixMaxLat - intersection.maxLatitude.inDegrees) / matrixDeltaLat
        val tMax = (matrixMaxLat - intersection.minLatitude.inDegrees) / matrixDeltaLat
        val vMin = (rasterHeight * tMin).toInt()
        val vMax = (rasterHeight * tMax + ALMOST_ONE).toInt()
        val jMin = vMin.coerceIn(0, rasterHeight - 1)
        val jMax = vMax.coerceIn(0, rasterHeight - 1)
        for (row in tileBlock.rows.keys) {
            val rowJMin = row * tileHeight
            val rowJMax = rowJMin + tileHeight - 1
            val j0 = jMin.coerceIn(rowJMin, rowJMax) % tileHeight
            val j1 = jMax.coerceIn(rowJMin, rowJMax) % tileHeight
            for (col in tileBlock.cols.keys) {
                val image = tileBlock.getTileImage(row, col) ?: continue
                if (!image.hasData) continue
                // Fast path: query sector fully contains this tile → use its cached min/max, no scan.
                if (sector.contains(tileBlock.tileMatrix.tileSector(row, col))) {
                    if (result[0] > image.minElevation) result[0] = image.minElevation
                    if (result[1] < image.maxElevation) result[1] = image.maxElevation
                    continue
                }
                // Slow path: partial overlap — scan only the intersecting sub-rectangle.
                val colIMin = col * tileWidth
                val colIMax = colIMin + tileWidth - 1
                val i0 = iMin.coerceIn(colIMin, colIMax) % tileWidth
                val i1 = iMax.coerceIn(colIMin, colIMax) % tileWidth
                val tileArray = image.array
                for (j in j0..j1) for (i in i0..i1) {
                    val texel = tileArray[i + j * tileWidth]
                    if (texel != NO_DATA) {
                        if (result[0] > texel) result[0] = texel.toFloat()
                        if (result[1] < texel) result[1] = texel.toFloat()
                    }
                }
            }
        }
    }

    protected open suspend fun processTiles(sector: Sector, minIdx: Int, maxIdx: Int, process: suspend (Tile) -> Unit) {
        for (idx in minIdx..maxIdx) {
            val tileMatrix = tileMatrixSet.entries[idx]
            val deltaLat = tileMatrix.sector.deltaLatitude.inDegrees / tileMatrix.matrixHeight
            val deltaLon = tileMatrix.sector.deltaLongitude.inDegrees / tileMatrix.matrixWidth
            val minRow = ((tileMatrix.sector.maxLatitude.inDegrees - sector.maxLatitude.inDegrees) / deltaLat).toInt()
            val maxRow = ((tileMatrix.sector.maxLatitude.inDegrees - sector.minLatitude.inDegrees) / deltaLat).toInt()
            val minCol = ((sector.minLongitude.inDegrees - tileMatrix.sector.minLongitude.inDegrees) / deltaLon).toInt()
            val maxCol = ((sector.maxLongitude.inDegrees - tileMatrix.sector.minLongitude.inDegrees) / deltaLon).toInt()
            for (row in minRow..maxRow) for (col in minCol..maxCol) process(Tile(tileMatrix, row, col))
        }
    }

    protected data class Tile(val tileMatrix: TileMatrix, val row: Int, val col: Int)

    protected open class TileBlock {
        lateinit var tileMatrix: TileMatrix
        val rows = mutableMapOf<Int, Int>()
        val cols = mutableMapOf<Int, Int>()
        private val images = mutableMapOf<Long, ElevationImage>()
        private var texelRow = -1
        private var texelCol = -1
        private var texelImage: ElevationImage? = null

        open fun clear() {
            rows.clear()
            cols.clear()
            images.clear()
            texelRow = -1
            texelCol = -1
            texelImage = null
        }

        fun putTileImage(row: Int, column: Int, image: ElevationImage) {
            images[tileMatrix.tileKey(row, column)] = image
        }

        fun getTileImage(row: Int, column: Int): ElevationImage? {
            if (texelRow != row || texelCol != column) {
                texelRow = row
                texelCol = column
                texelImage = images[tileMatrix.tileKey(row, column)]
            }
            return texelImage
        }

        fun readTexel(row: Int, column: Int, i: Int, j: Int) =
            getTileImage(row, column)?.array?.get(i + j * tileMatrix.tileWidth) ?: NO_DATA
    }
}